import 'dotenv/config';
import { prisma } from '../src/lib/prisma.js';
import { hashPassword } from '../src/lib/passwords.js';

// Dev-only password. The seed refuses to run in production.
if (process.env.NODE_ENV === 'production') throw new Error('Refusing to seed production');
// Read a required variable, or stop with a clear message. The return type is plain `string`.
function requireEnv(name: string): string {
  const value = process.env[name];
  if (!value) throw new Error(`${name} is not set: run ./scripts/setup-env.sh`);
  return value;
}

// Dev-only. Comes from .env (generated by scripts/setup-env.sh), so it's never committed.
const DEV_PASSWORD = requireEnv('SEED_PASSWORD');
async function main() {
  const passwordHash = await hashPassword(DEV_PASSWORD);

  const people = [
    { email: 'admin@example.com', fullName: 'Ada Admin', role: 'ADMIN' },
    { email: 'support@example.com', fullName: 'Sam Support', role: 'SUPPORT' },
    { email: 'alice@example.com', fullName: 'Alice Customer', role: 'CUSTOMER' },
    { email: 'bob@example.com', fullName: 'Bob Customer', role: 'CUSTOMER' },
  ] as const;
  for (const p of people) {
    // upsert makes the seed safe to run repeatedly
    await prisma.customer.upsert({ where: { email: p.email }, update: {}, create: { ...p, passwordHash } });
  }

  const systems = [
    { key: 'billing', name: 'Billing', description: 'Invoices and payments', maxLevel: 'WRITE' },
    { key: 'crm', name: 'CRM', description: 'Customer relationship management', maxLevel: 'ADMIN' },
    { key: 'data-warehouse', name: 'Data warehouse', description: 'Analytics read replica', maxLevel: 'READ' },
  ] as const;
  for (const s of systems) {
    await prisma.backendSystem.upsert({ where: { key: s.key }, update: {}, create: s });
  }

  const purposes = [
    { key: 'terms_of_service', description: 'Agreement to the terms of service', required: true },
    { key: 'marketing_email', description: 'Receive marketing emails', required: false },
    { key: 'analytics', description: 'Use of usage data for product analytics', required: false },
    { key: 'partner_sharing', description: 'Share data with selected partners', required: false },
  ];
  for (const p of purposes) {
    await prisma.consentPurpose.upsert({ where: { key: p.key }, update: {}, create: p });
  }

  console.log('Seeded. Seeded users sign in with SEED_PASSWORD from your .env file.');
}

main().finally(() => prisma.$disconnect());